import pyomo.environ as pyo

DATA = {
    "products": ["hardwood", "vinyl"],
    "profit": {"hardwood": 2.5, "vinyl": 3.0},
    "min_demand": {"hardwood": 20000.0, "vinyl": 10000.0},
    "max_production": {"hardwood": 50000.0, "vinyl": 30000.0},
    "min_shipping_total": 60000.0,
}

def build_model(data=None):
    d = data or DATA
    products = d["products"]
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=products)

    def lower_bound(m, p):
        return (d["min_demand"][p], d["max_production"][p])

    model.x = pyo.Var(
        model.P,
        within=pyo.NonNegativeReals,
        bounds=lower_bound,
    )

    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def min_demand_rule(m, p):
        return m.x[p] >= d["min_demand"][p]

    model.min_demand = pyo.Constraint(model.P, rule=min_demand_rule)

    def max_production_rule(m, p):
        return m.x[p] <= d["max_production"][p]

    model.max_production = pyo.Constraint(model.P, rule=max_production_rule)

    def shipping_rule(m):
        return sum(m.x[p] for p in m.P) >= d["min_shipping_total"]

    model.shipping_total = pyo.Constraint(rule=shipping_rule)

    return model
